'use client';
import { useState } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { FlaskConical, Fingerprint, Network, ScanSearch, Mail, FileCheck2, BrainCircuit, ArrowRight, ArrowUpRight, Clock3, CheckCircle2, ShieldCheck, ArrowLeft, RotateCcw, Download, Printer, type LucideIcon } from 'lucide-react';
import { labs } from '@/lib/course';
import type { Lab } from '@/lib/types';
import { PageHeading, InfoNote } from './ui';
import { useWorkspace } from './WorkspaceProvider';
import Simulation from './labs/Simulations';
export const labIcons: Record<string, LucideIcon> = { acquisition: ScanSearch, hash: Fingerprint, osint: Network, network: Network, email: Mail, certificate: FileCheck2, ai: BrainCircuit };
export function downloadText(name: string, text: string, type = 'application/json') { const url = URL.createObjectURL(new Blob([text], { type })); const a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
export default function Labs() {
  const [filter, setFilter] = useState(0); const { state } = useWorkspace(); const completed = labs.filter(l => state.labs[l.id]?.completed).length;
  return <div className="page-enter"><PageHeading eyebrow="LESS WATCHING. MORE DISCOVERING." title="Your ideas. Put to the test." description="Seven guided simulations. Safe datasets. Real decisions. Build the thinking behind a reliable investigation."><span className="labs-completed"><CheckCircle2 size={17} />{completed} of {labs.length} labs completed</span></PageHeading><section className="labs-hero"><div><span className="hero-eyebrow"><span />THE TRACE FORENSIC LAB</span><h2>Every click leaves a trace.<br />What will you do with it?</h2><p>Step into a fictional investigation. Preserve the evidence, test your assumptions, and explain what you find.</p><Link href="/labs/acquisition" className="button hero-button">Begin your first investigation<ArrowRight size={16} /></Link><span className="lab-safe-note"><ShieldCheck size={14} />No live systems. No real personal data.</span></div><Image src="/images/forensic-desk.png" alt="A digital forensic investigation desk" fill sizes="(max-width: 700px) 100vw, 50vw" /></section><div className="filter-bar"><div className="filter-chips"><button className={`filter-chip ${filter === 0 ? 'active' : ''}`} onClick={() => setFilter(0)}>All labs <span>7</span></button>{[1, 2, 3, 4, 5].map(u => <button key={u} className={`filter-chip ${filter === u ? 'active' : ''}`} onClick={() => setFilter(u)}>Unit {['I', 'II', 'III', 'IV', 'V'][u - 1]}</button>)}</div><span className="library-count">Learn by making decisions</span></div><div className="lab-card-grid">{labs.filter(l => !filter || l.unit === filter).map((lab, i) => { const Icon = labIcons[lab.type]; const done = state.labs[lab.id]?.completed; return <Link className={`lab-card ${lab.type === 'ai' ? 'ai-featured' : ''}`} href={`/labs/${lab.id}`} key={lab.id}><div className="card-topline"><span className={`lab-card-icon ${lab.type === 'ai' ? 'ai' : ''}`}><Icon size={25} strokeWidth={1.5} /></span><span className={`tag ${done ? 'tag-teal' : 'tag-muted'}`}>{done ? <><CheckCircle2 size={11} />COMPLETED</> : `LAB ${String(labs.indexOf(lab) + 1).padStart(2, '0')}`}</span></div><h2>{lab.title}</h2><p>{lab.description}</p><div className="lab-skill-tags">{lab.skills.map(s => <span key={s}>{s}</span>)}</div><div className="lab-card-footer"><span><Clock3 size={13} />{lab.minutes} min <i />Unit {lab.unit}</span><span className="text-link">{done ? 'Revisit lab' : 'Enter lab'}<ArrowUpRight size={15} /></span></div></Link>; })}</div><InfoNote>These are educational simulations, not live forensic tools. Disk acquisition and OSINT use fictional scenarios; SHA-256 hashing is real and runs locally. Never practise on a real person or system without authority.</InfoNote></div>;
}
export function LabRunner({ lab }: { lab: Lab }) {
  const { state, recordLab, ready } = useWorkspace(); const [run, setRun] = useState(0); const record = state.labs[lab.id]; const Icon = labIcons[lab.type]; const index = labs.findIndex(l => l.id === lab.id); const next = labs[(index + 1) % labs.length];
  return <div className="page-enter lab-runner" key={`${lab.id}-${run}`}><Link className="back-link" href="/labs"><ArrowLeft size={14} />Back to the lab</Link><div className="lab-runner-header"><span className="tag tag-teal"><FlaskConical size={13} />INTERACTIVE SIMULATION · UNIT {lab.unit}</span><h1>{lab.title}</h1><p>{lab.subtitle}</p><div className="lab-runner-meta"><span><Clock3 size={14} />{lab.minutes} minutes</span><span><ShieldCheck size={14} />Fictional, safe environment</span>{record?.completed && <span className="text-teal-700"><CheckCircle2 size={14} />Completed</span>}</div></div><div className="lab-runner-layout"><div><InfoNote>{lab.description}</InfoNote><Simulation key={`${lab.id}-${run}`} lab={lab} completed={!!record?.completed} onComplete={result => recordLab(lab.id, result)} />{record?.completed && <div className="lab-completion-banner" role="status"><CheckCircle2 size={27} /><div><h3>A sound investigation starts with good thinking.</h3><p>Your completion is saved. Revisit the lab any time, or take your reasoning to the next challenge.</p></div><Link href={`/labs/${next.id}`} className="button button-primary">Next lab<ArrowRight size={15} /></Link></div>}<div className="lab-run-actions"><button className="text-link" onClick={() => setRun(r => r + 1)}><RotateCcw size={14} />Restart this run</button>{record && <button className="text-link" onClick={() => downloadText(`trace-${lab.id}-result.json`, JSON.stringify({ lab: lab.title, training: true, ...record }, null, 2))}><Download size={14} />Export result</button>}<Link href={`/print?lab=${lab.id}`} className="text-link"><Printer size={14} />Print lab worksheet</Link></div></div><aside><div className="lab-mission"><span className="lab-mission-icon"><Icon size={28} /></span><span className="eyebrow">YOUR MISSION</span><h3>Think like an investigator.</h3><ol>{lab.steps.map((s, i) => <li key={s}><span>{record?.completed ? <CheckCircle2 size={15} /> : i + 1}</span>{s}</li>)}</ol><div className="lab-mission-note"><ShieldCheck size={17} /><p>Observe carefully. Separate facts from inferences. Explain your limitations.</p></div></div><div className="lab-related"><h3>The knowledge behind it</h3><Link href={`/topics/${lab.id === 'email' ? '3.11' : lab.id === 'hash' ? '4.4' : lab.id === 'certificate' ? '2.10' : lab.id === 'ai' ? '5.9' : lab.id === 'osint' ? '3.2' : lab.id === 'network' ? '3.9' : '2.6'}`}>Read the connected lesson<ArrowUpRight size={14} /></Link><Link href="/cases/invoice">Explore the invoice case<ArrowUpRight size={14} /></Link></div>{!ready && <p className="text-xs text-slate-400 mt-4">Connecting your saved workspace…</p>}</aside></div></div>;
}
