'use client';
import { useState } from 'react';
import { Fingerprint, ArrowRight, CheckCircle2, Download, RotateCcw, FileText, ShieldCheck, LoaderCircle } from 'lucide-react';
import { InfoNote } from '../ui';
export type SimulationProps = { onComplete: (result: string) => void; completed: boolean };
const originalText = 'NORTHSTAR STUDIO · TRAINING EVIDENCE\nInvoice: NS-2026-014\nBeneficiary: Example Supplies\nAmount: 24500.00 INR\nAccount: DEMO-0001842\nAuthorized by: Maya';
async function sha256(text: string) { const bytes = new TextEncoder().encode(text); const digest = await crypto.subtle.digest('SHA-256', bytes); return Array.from(new Uint8Array(digest)).map(b => b.toString(16).padStart(2, '0')).join(''); }
export default function HashLab({ onComplete, completed }: SimulationProps) {
  const [text, setText] = useState(originalText); const [original, setOriginal] = useState(''); const [changed, setChanged] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const calculate = async () => { setBusy(true); setError(''); try { const hash = await sha256(text); if (!original) setOriginal(hash); else setChanged(hash); } catch { setError('Hashing is unavailable in this browser context. Open the lab over HTTPS or localhost.'); } finally { setBusy(false); } };
  const download = () => { const blob = new Blob([JSON.stringify({ training: true, algorithm: 'SHA-256', originalText, originalHash: original, alteredText: text, alteredHash: changed, match: original === changed, limitation: 'Integrity only. Does not establish authorship, truth, or admissibility.' }, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'trace-integrity-worksheet.json'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000); };
  return <div className="simulation-panel"><div className="simulation-title"><Fingerprint size={23} /><div><h2>Meet the fingerprint of a file.</h2><p>Same input, same hash. Change a bit, change the story.</p></div></div><div className="hash-workbench"><label className="field-label" htmlFor="evidence-text">01 / Your fictional evidence</label><textarea id="evidence-text" className="code-input" value={text} readOnly={!!original} onChange={e => { setText(e.target.value); setChanged(''); }} rows={7} spellCheck={false} /><div className="hash-actions">{!original ? <button className="button button-primary" onClick={calculate} disabled={busy || !text}>{busy ? <LoaderCircle size={16} className="animate-spin" /> : <Fingerprint size={16} />}Calculate original SHA-256</button> : <><button className="button button-primary" onClick={calculate} disabled={busy || text === originalText}>{busy ? <LoaderCircle size={16} className="animate-spin" /> : <ArrowRight size={16} />}Hash altered evidence</button><button className="text-link" onClick={() => { setOriginal(''); setChanged(''); setText(originalText); }}><RotateCcw size={14} />Reset</button></>}</div>{original && !changed && <InfoNote>Now change the account number, an amount, or even one letter. The original has been preserved for comparison.</InfoNote>}{error && <p className="form-error" role="alert">{error}</p>}<div className="hash-result"><span><FileText size={14} />ORIGINAL EVIDENCE</span><code>{original || 'Your original fingerprint will appear here.'}</code>{original && <small><CheckCircle2 size={12} />Reference recorded</small>}</div>{changed && <div className={`hash-result ${changed !== original ? 'changed' : ''}`}><span><Fingerprint size={14} />ALTERED EVIDENCE</span><code>{changed}</code><small>{changed === original ? 'Identical content — matching fingerprint.' : 'Different content — different fingerprint.'}</small></div>}</div>{changed && <div className="lab-conclusion"><ShieldCheck size={24} /><div><h3>{changed !== original ? 'One small edit. A completely different hash.' : 'The content still matches.'}</h3><p>A matching hash supports integrity. It does not prove who created the invoice, whether the payment was authorized, or whether the evidence is admissible.</p></div></div>}<div className="simulation-footer"><button className="text-link" disabled={!original || !changed} onClick={download}><Download size={15} />Download worksheet</button><button className="button button-primary" disabled={!original || !changed || completed} onClick={() => onComplete(JSON.stringify({ originalHash: original, alteredHash: changed, match: original === changed, algorithm: 'SHA-256' }))}>{completed ? <CheckCircle2 size={16} /> : <CheckCircle2 size={16} />}{completed ? 'Lab completed' : 'Complete the integrity lab'}</button></div><p className="simulation-privacy">Calculated locally with the Web Crypto API. Your text is not uploaded.</p></div>;
}
