'use client';
import { useEffect, useMemo, useRef, useState } from 'react';
import { Chart, LineController, LineElement, PointElement, LinearScale, CategoryScale, Tooltip, Legend, Filler } from 'chart.js';
import { BrainCircuit, CheckCircle2, SlidersHorizontal, ShieldCheck } from 'lucide-react';
import type { SimulationProps } from './HashLab';
import { InfoNote } from '../ui';
Chart.register(LineController, LineElement, PointElement, LinearScale, CategoryScale, Tooltip, Legend, Filler);
const data = Array.from({ length: 100 }, (_, i) => ({ id: `MSG-${String(i + 1).padStart(3, '0')}`, positive: i < 20, score: i < 20 ? 0.35 + i * 0.032 : 0.05 + (i % 80) * 0.009 }));
const thresholds = Array.from({ length: 19 }, (_, i) => (i + 1) * 5);
function metrics(threshold: number) { const t = threshold / 100; const tp = data.filter(d => d.positive && d.score >= t).length; const fp = data.filter(d => !d.positive && d.score >= t).length; const fn = data.filter(d => d.positive && d.score < t).length; const tn = 100 - tp - fp - fn; return { tp, fp, fn, tn, precision: tp + fp ? tp / (tp + fp) : 0, recall: tp / 20, fpr: fp / 80 }; }
const pct = (n: number) => `${Math.round(n * 100)}%`;
export default function AILab({ onComplete, completed }: SimulationProps) {
  const [threshold, setThreshold] = useState(50); const [moved, setMoved] = useState(false); const [policy, setPolicy] = useState(''); const canvas = useRef<HTMLCanvasElement>(null); const chart = useRef<Chart<'line', (number | null)[], string> | null>(null); const m = useMemo(() => metrics(threshold), [threshold]);
  useEffect(() => {
    if (!canvas.current) return;
    chart.current = new Chart<'line', (number | null)[], string>(canvas.current, { type: 'line', data: { labels: thresholds.map(String), datasets: [
      { label: 'Precision', data: thresholds.map(t => metrics(t).precision * 100), borderColor: '#168c7c', backgroundColor: '#168c7c12', borderWidth: 2, tension: 0.25, pointRadius: 0, fill: true },
      { label: 'Recall', data: thresholds.map(t => metrics(t).recall * 100), borderColor: '#d3a362', borderWidth: 2, tension: 0.25, pointRadius: 0 },
      { label: 'Current recall', data: thresholds.map(t => t === 50 ? metrics(50).recall * 100 : null), borderColor: '#168c7c', backgroundColor: '#168c7c', pointRadius: 6, showLine: false },
    ] }, options: { responsive: true, maintainAspectRatio: false, animation: { duration: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 0 : 250 }, interaction: { mode: 'index', intersect: false }, plugins: { legend: { labels: { filter: item => item.text !== 'Current recall', usePointStyle: true, boxWidth: 7, font: { family: 'DM Sans', size: 10 } } }, tooltip: { callbacks: { title: items => `Threshold: ${items[0]?.label}%`, label: item => `${item.dataset.label}: ${Math.round(Number(item.raw))}%` } } }, scales: { x: { title: { display: true, text: 'Decision threshold (%)', font: { size: 10 } }, grid: { display: false }, ticks: { maxTicksLimit: 7, font: { size: 9 } } }, y: { min: 0, max: 105, ticks: { stepSize: 25, font: { size: 9 }, callback: value => `${value}%` }, grid: { color: '#edf1ef' } } } } });
    return () => { chart.current?.destroy(); chart.current = null; };
  }, []);
  useEffect(() => { if (!chart.current) return; chart.current.data.datasets[2].data = thresholds.map(t => t === threshold ? metrics(threshold).recall * 100 : null); chart.current.update(); }, [threshold]);
  return <div className="simulation-panel"><div className="simulation-title"><BrainCircuit size={25} /><div><h2>An alert is a question, not a verdict.</h2><p>Explore a fixed, synthetic validation set: 20 threats and 80 benign messages.</p></div></div><div className="ai-metrics"><div><span>PRECISION</span><strong>{pct(m.precision)}</strong><small>Of flagged messages, how many are threats?</small></div><div><span>RECALL</span><strong>{pct(m.recall)}</strong><small>Of actual threats, how many did we find?</small></div><div><span>FALSE POSITIVE RATE</span><strong>{pct(m.fpr)}</strong><small>Of benign messages, how many were flagged?</small></div></div><div className="threshold-control"><label htmlFor="ai-threshold"><SlidersHorizontal size={16} />Decision threshold <strong>{threshold}%</strong></label><input id="ai-threshold" type="range" min={5} max={95} step={5} value={threshold} onChange={e => { setThreshold(Number(e.target.value)); setMoved(true); }} /><div><span>More alerts · fewer missed threats</span><span>Fewer alerts · more missed threats</span></div></div><div className="ai-chart"><canvas ref={canvas} role="img" aria-label={`Precision ${pct(m.precision)}, recall ${pct(m.recall)} at threshold ${threshold} percent. Exact values are also shown above and in the confusion matrix.`} /></div><div className="ai-bottom"><div><h3>The confusion matrix</h3><div className="confusion-matrix"><div className="tp"><span>True positives</span><strong>{m.tp}</strong></div><div className="fp"><span>False positives</span><strong>{m.fp}</strong></div><div className="fn"><span>False negatives</span><strong>{m.fn}</strong></div><div className="tn"><span>True negatives</span><strong>{m.tn}</strong></div></div></div><div className="ai-samples"><h3>A few records behind the numbers</h3>{data.filter((_, i) => i % 17 === 0).map(d => <div key={d.id}><code>{d.id}</code><span>{d.score.toFixed(2)}</span><small>{d.positive ? 'Threat' : 'Benign'}</small><strong className={d.score >= threshold / 100 ? 'flagged' : ''}>{d.score >= threshold / 100 ? 'Flagged' : 'Not flagged'}</strong></div>)}</div></div><label className="field-label" htmlFor="ai-policy">Choose a responsible review policy</label><select id="ai-policy" className="form-input" value={policy} onChange={e => setPolicy(e.target.value)}><option value="">Select your approach…</option><option value="human">Review alerts, verify original evidence, and sample non-alerts for missed threats.</option><option value="auto">Automatically declare every flagged sender guilty.</option><option value="ignore">Ignore the model’s errors because the dataset is large.</option></select>{policy && policy !== 'human' && <p className="form-error">A model score is not proof of guilt. Choose a policy with verification and error monitoring.</p>}<InfoNote>This is a deterministic teaching dataset, not a trained or deployed detector. Real performance requires representative, separate validation data and ongoing monitoring.</InfoNote><div className="simulation-footer"><span className="text-xs text-slate-400 flex items-center gap-2"><ShieldCheck size={14} />Human judgment stays in the loop.</span><button className="button button-primary" disabled={!moved || policy !== 'human' || completed} onClick={() => onComplete(JSON.stringify({ threshold, ...m, policy: 'Human review, original-source verification, and negative sampling', dataset: '100 fixed synthetic records' }))}><CheckCircle2 size={16} />{completed ? 'Lab completed' : 'Complete the AI lab'}</button></div></div>;
}
